# Hand-compiled records. Summaries are written for this archive; no source text is reproduced.
# Fields: date, relation, type, title, venue, url, status, topics, summary
# relation: by (bylined or authored by her) | with (she speaks or appears) | about (written about her)
# status: opened (the page itself was read) | listed (confirmed by an author page, publisher listing or platform API)
#         | search (surfaced in a search result only; open it before citing)
YT = "https://www.youtube.com/watch?v="
E = []
def a(date, rel, typ, title, venue, url, status, topics, summary):
    E.append(dict(date=date, relation=rel, type=typ, title=title, venue=venue, url=url,
                  status=status, topics=topics.split(","), summary=summary))

